static inline int nd_deck_source_view(const char sha[65]) {
    if (!strcmp(sha,"f8090bf1dba07e128deb24f35287b4eb2f74470db037835e0f980a9a40a320a8")) return 2;
    if (!strcmp(sha,"394488664f2e1fa0fd8c898a2f6757a5fc012c295551e487e4bf37dc5da8af98")) return 1;
    if (!strcmp(sha,"2b9240133388bb52b107ac15ece79f15ff0cb10a00e381a80913f4ff1c436145")) return 2;
    if (!strcmp(sha,"46bc67f54026e30cbe773a7a3afc347a6516d6ce1d27f8b271d65622982d47ca")) return 1;
    if (!strcmp(sha,"8e8bc0e26ea1c0347075af88efb87e3c0b576f3a4232de4722d436f2d4d0164b")) return 2;
    if (!strcmp(sha,"804596d69e2d6b87fff9bc5d1bea845381bb8cd1e6791f44114e96ef34c7d1de")) return 1;
    return 0;
}
static inline int nd_deck_unpack(int view, uint8_t *out, size_t bytes) {
    if (!out || bytes < ND_DECK_BYTES || (view != 1 && view != 2)) return -1;
    const nd_deck_run *runs = view == 1 ? nd_deck_front : nd_deck_inclined;
    size_t count = view == 1 ? sizeof nd_deck_front/sizeof *runs : sizeof nd_deck_inclined/sizeof *runs;
    size_t total=0;
    for (size_t i=0;i<count;i++) {
        if (!runs[i].n || runs[i].n > ND_DECK_W*ND_DECK_H-total) return -1;
        total += runs[i].n;
    }
    if (total != ND_DECK_W*ND_DECK_H) return -1;
    size_t at=0;
    for (size_t i=0;i<count;i++) for (unsigned j=0;j<runs[i].n;j++) {
        out[at++]=runs[i].grey; out[at++]=runs[i].grey;
        out[at++]=runs[i].grey; out[at++]=runs[i].alpha;
    }
    return 0;
}
